/**
 * The `widgets` page type: every widget of a project, generated by @saasreport/widgets (`kit widgets build`) from the
 * project's widgets.spec.json and its contracts. The site renders what the generated file holds; it adds no content.
 *
 *   { type: "widgets", path: "/examples/", generated: <widgets.generated.json>, registry?: <the widgets Registry from registryFor(spec, dir), when the spec declares its own plugins>,
 *     content: { <locale>: { meta?: { title, description, ogImage }, title?, intro?, chrome?: { …runtime words } } } }
 *
 * Styles: the theme's widgets.css (from @saasreport/widgets, rendered with the project's tokens); script: widgets.js
 * (the widget runtime). The page carries the site's chrome (bar, footer, icons, fonts) via innerPage.
 */
import { renderWidgetsBody } from "../../../widgets/src/html.js";
import { kitRegistry, isRegistry } from "../../../widgets/src/registry.js";
import { innerPage, webPageLd, crumbsLd } from "./shell.js";

export const GENERATED_SCHEMA = "kit.widgets-generated.v1";

/** Problems with a widgets page config (the generated file itself is checked by `kit widgets check`). */
export function checkWidgetsPage(page, codes = []) {
  const p = [];
  const g = page.generated;
  if (!g || g.schema !== GENERATED_SCHEMA) return [`pages[${page.path}]: generated must be a ${GENERATED_SCHEMA} file (kit widgets build)`];
  if (page.registry !== undefined && !isRegistry(page.registry)) return [...p, `pages[${page.path}]: registry must be the widgets Registry from registryFor(spec, dir)`];
  const reg = page.registry || kitRegistry();
  for (const id of new Set((g.widgets || []).map((w) => w.archetype))) if (!reg.has(id)) p.push(`pages[${page.path}]: widgets use the archetype "${id}", which is not registered; pass the project's registry (registryFor(spec, dir)) as the page's \`registry\``);
  for (const code of codes) if (page.content?.[code] && !g.locales.some((l) => l.code === code)) p.push(`pages[${page.path}]: content for ${code} but widgets.generated.json has no ${code} widgets`);
  if (g.page) for (const [code, pg] of Object.entries(g.page)) if (pg.path !== page.path) p.push(`pages[${page.path}]: widgets.spec.json build.page.path is ${pg.path} (${code})`);
  return p;
}

export function renderWidgetsPage(page, ctx) {
  const code = ctx.L.code;
  const c = page.content?.[code] || {};
  const g = page.generated;
  const gp = g.page?.[code] || {};
  const title = c.meta?.title || c.title || gp.title;
  const description = c.meta?.description || c.intro || gp.intro || title;
  const u = ctx.url + ctx.pathOf(page.path);
  const body = renderWidgetsBody(g, code, { chrome: c.chrome, title: c.title, intro: c.intro, registry: page.registry || kitRegistry() });
  return {
    "index.html": innerPage(ctx, {
      path: page.path, title, description, ogImage: c.meta?.ogImage,
      graph: [webPageLd({ type: "CollectionPage", name: title, description, url: u, ctx }), crumbsLd([[ctx.chrome.strings.home, ctx.homeUrl], [title, u]])],
      styles: ["/widgets.css"], scripts: ["/widgets.js"], bodyClass: "tpage kw-body", body, generator: "@saasreport/widgets", bar: c.bar,
    }),
  };
}
